const payload = $input.first()?.json ?? {};
const files = Array.isArray(payload.files) ? payload.files : [];
const now = Math.floor(Date.now() / 1000);
const videoExt = new Set(['.mkv', '.mp4', '.avi', '.m4v', '.mov', '.webm', '.mpg', '.mpeg']);
const invalidCharacters = "<>:" + String.fromCharCode(47,92) + "|?*";
const invalidPart = part => [...part].some(char => invalidCharacters.includes(char) || char.charCodeAt(0) < 32);
function clean(value) {
  const bad = new Set(['<', '>', ':', String.fromCharCode(92), '|', '?', '*']);
  return Array.from(value, char => bad.has(char) || char.charCodeAt(0) < 32 ? ' ' : char).join('').replace(/[._]+/g, ' ').replace(/\s+/g, ' ').trim().replace(/[. ]+$/g, '');
}
function reviewDestination(name, path, ext) {
  const stem = clean(name.slice(0, -ext.length)) || 'video';
  let hash = 2166136261;
  for (const char of path) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619) >>> 0;
  return `Review/${stem} [${hash.toString(16).padStart(8, '0')}]${ext}`;
}
const result = [];
for (const file of files) {
  if (!file || typeof file.name !== 'string' || !Number.isFinite(file.mtime) || now - file.mtime < 600) continue;
  const relativePath = typeof file.path === 'string' ? file.path : file.name;
  const parts = relativePath.split('/');
  if (relativePath.length > 4096 || parts.length > 17 || parts.some(part => !part || part === '.' || part === '..' || invalidPart(part))) continue;
  const dot = file.name.lastIndexOf('.');
  if (dot < 1) continue;
  const ext = file.name.slice(dot).toLowerCase();
  if (!videoExt.has(ext)) continue;
  const source = `Inbox/${relativePath}`;
  const base = file.name.slice(0, dot).replace(/[._]+/g, ' ').replace(/\s+/g, ' ').trim();
  const review = reviewDestination(file.name, relativePath, ext);
  let match = base.match(/^(.+?)\s*\(((?:19|20)\d{2})\)(?:$|[ ._-].*)$/);
  if (match) {
    const title = clean(match[1]);
    const year = match[2];
    if (!title) { result.push({ json: { source, destination: review, kind: 'review' } }); continue; }
    const folder = `${title} (${year})`;
    result.push({ json: { source, destination: `Movies/${folder}/${folder}${ext}`, kind: 'movie', title, year } });
    continue;
  }
  match = base.match(/^(.+?)\s+[.-]?\s*S(\d{1,2})E(\d{1,3})(?:\s*[-._ ]+(.*))?$/i);
  if (match) {
    const title = clean(match[1]);
    const season = Number(match[2]);
    const episode = Number(match[3]);
    const episodeTitle = clean(match[4] || '');
    if (title && season <= 99 && episode >= 1 && episode <= 999) {
      const code = `S${String(season).padStart(2, '0')}E${String(episode).padStart(2, '0')}`;
      const filename = `${title} - ${code}${episodeTitle ? ` - ${episodeTitle}` : ''}${ext}`;
      result.push({ json: { source, destination: `Shows/${title}/Season ${String(season).padStart(2, '0')}/${filename}`, kind: 'episode', title, season, episode } });
      continue;
    }
  }
  result.push({ json: { source, destination: review, kind: 'review' } });
}
return result;
